	["Dark Mode"] = "Тёмный режим", -- draft
	["Darkens the painted reskin (its brightness below) and, where the reskin is off, the game's own art of unit frames, bars, nameplates, auras and menus."] = "Затемняет рисованный облик (его яркость ниже), а там, где облик выключен, собственное оформление игры у рамок, полос, индикаторов здоровья, эффектов и меню.", -- draft
	["Vendor Automation"] = "Автоматизация торговца", -- draft
