	-- UnitFramePanel
	["Unit Frames Kit"] = "Набор рамок", -- draft
	["The player, target, focus and pet frames dressed in the painted kit on the game's own layout."] = "Рамки игрока, цели, фокуса и питомца в рисованном наборе в раскладке игры.", -- draft
	["Elite and Rare Marks"] = "Метки элиты и редких", -- draft
	["The target's and focus's portrait ring and level circle in gold for an elite, silver for a rare or rare elite and red-bronze for a boss, with a small crest on the ring's top gem: a crown, a silver star, a gold star or a skull. Their target's ring too."] = "Кольцо портрета и круг уровня цели и фокуса золотые для элиты, серебряные для редкого или редкого элитного и красно-бронзовые для босса, с маленьким гербом на верхнем самоцвете кольца: корона, серебряная звезда, золотая звезда или череп. И кольцо их цели тоже.", -- draft
	["Bar Background"] = "Фон полос", -- draft
	["What lies behind the health and power bars, under the fill, the heals coming in and the bars' borders: the painted dark trough, a flat dark, the Bar Texture's finish in the dark, or nothing. Every unit frame: the player, target, focus, pet, target of target and party."] = "Что лежит за полосами здоровья и ресурса, под заливкой, входящим исцелением и рамками полос: рисованный тёмный жёлоб, плоская тьма, отделка «Текстуры полос» в тёмном или ничего. Каждая рамка: игрок, цель, фокус, питомец, цель цели и группа.", -- draft
	["Painted Trough"] = "Рисованный жёлоб", -- draft
	["Bar Texture, Dark"] = "«Текстура полос», тёмная", -- draft
	["Bar Background Opacity"] = "Непрозрачность фона полос", -- draft
	["How solid the bars' background is: lower lets the world show through the empty part of a bar."] = "Насколько плотен фон полос: меньше — и мир просвечивает сквозь пустую часть полосы.", -- draft
	["Frame Backdrop"] = "Подложка рамок", -- draft
	["A backdrop round the player, target and focus frames: stone behind the portrait, the name and the bars, framed by the red or iron gems of the action bars' backdrops or by one of the border styles of Look > Borders (its inner corners mitred)."] = "Подложка вокруг рамок игрока, цели и фокуса: камень за портретом, именем и полосами в обрамлении красных или железных самоцветов подложек панелей команд или одного из стилей рамок из Облик > Рамки (внутренние углы скошены).", -- draft
	["Red gems"] = "Красные самоцветы", -- draft
	["Iron gems"] = "Железные самоцветы", -- draft
	["Frame Backdrop Background"] = "Фон подложки рамок", -- draft
	["What lies behind the player, target and focus frames inside their backdrop."] = "Что лежит за рамками игрока, цели и фокуса внутри их подложки.", -- draft
	-- CastBarPanel
	["Cast Bars Kit"] = "Набор индикаторов заклинаний", -- draft
	["The cast bars dressed in the painted kit on the game's own layout."] = "Индикаторы заклинаний в рисованном наборе в раскладке игры.", -- draft
	-- RaidFramePanel
	["Raid Frames Kit"] = "Набор рамок рейда", -- draft
	["The compact raid and party frames and the totem bar dressed in the painted kit on the game's own layout."] = "Компактные рамки рейда и группы и панель тотемов в рисованном наборе в раскладке игры.", -- draft
	-- ActionBarPanel
	["Action Bars Kit"] = "Набор панелей команд", -- draft
	["The action bars, micro menu, bag bar and experience bars dressed in the painted kit on the game's own layout."] = "Панели команд, микроменю, панель сумок и индикаторы опыта в рисованном наборе в раскладке игры.", -- draft
	["The border of the backdrop round the action bars (and the experience and reputation bars): the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "Рамка подложки вокруг панелей команд (и индикаторов опыта и репутации): красные или железные самоцветы по углам или один из стилей рамок из Oldschool > Рамки (толстый, внутренние углы скошены). Подложка каждого элемента включается в «Панелях» (её «Подложка»); включённые элементы, стоящие вместе, делят одну подложку в облике первого из них: панель команд 1, другие панели, микроменю, панель сумок.", -- draft
	["Backdrop Background"] = "Фон подложки", -- draft
	["What lies behind the buttons inside the backdrop. All three are chosen with pictures on Oldschool > Frame Art."] = "Что лежит за кнопками внутри подложки. Все три выбираются по картинкам в Oldschool > Оформление рамок.", -- draft
	["Button Background"] = "Фон кнопки", -- draft
	["What a button shows inside its rim where it has no icon."] = "Что кнопка показывает внутри своего ободка там, где у неё нет значка.", -- draft
	["The border of the backdrop round the micro menu: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "Рамка подложки вокруг микроменю: красные или железные самоцветы по углам или один из стилей рамок из Oldschool > Рамки (толстый, внутренние углы скошены). Подложка каждого элемента включается в «Панелях» (её «Подложка»); включённые элементы, стоящие вместе, делят одну подложку в облике первого из них: панель команд 1, другие панели, микроменю, панель сумок.", -- draft
	["The border of the backdrop round the bag bar: the red or iron gems on its corners, or one of the border styles of Oldschool > Borders (drawn heavy, its inner corners mitred). Each element's backdrop is switched on on Bars (its Backdrop); switched-on elements placed together share one backdrop, in the look of the first of them: Action Bar 1, the other bars, the micro menu, the bag bar."] = "Рамка подложки вокруг панели сумок: красные или железные самоцветы по углам или один из стилей рамок из Oldschool > Рамки (толстый, внутренние углы скошены). Подложка каждого элемента включается в «Панелях» (её «Подложка»); включённые элементы, стоящие вместе, делят одну подложку в облике первого из них: панель команд 1, другие панели, микроменю, панель сумок.", -- draft
	-- BackpackPanel
	["Backpack Kit"] = "Набор рюкзака", -- draft
	["The bag windows dressed in the painted kit on the game's own layout."] = "Окна сумок в рисованном наборе в раскладке игры.", -- draft
	["What the bag windows show behind the items (Bags by Kind's window too, and the bank): cracked concrete (the window's own), stone, iron plate, parchment, leather or dark."] = "Что окна сумок показывают за предметами (окно «Сумок по видам» тоже, и банк): потрескавшийся бетон (собственный фон окна), камень, железную пластину, пергамент, кожу или тьму.", -- draft
	["Item Background"] = "Фон предмета", -- draft
	["What an empty bag slot shows inside its rim. Both are chosen with pictures on Windows > Bags. The slots' rim is the Button Border (Oldschool > Borders, every window's)."] = "Что пустая ячейка сумки показывает внутри ободка. Оба выбираются по картинкам в Окна > Сумки. Ободок ячеек — «Рамка кнопок» (Oldschool > Рамки, каждого окна).", -- draft
	-- MinimapKit
	["Minimap Kit"] = "Набор мини-карты", -- draft
	["The minimap dressed in the painted kit: the ring round the map (or the square map's painted border), the zone plate, the tracking button's rim and the zoom buttons."] = "Мини-карта в рисованном наборе: кольцо вокруг карты (или рисованная рамка квадратной карты), табличка зоны, ободок кнопки отслеживания и кнопки масштаба.", -- draft
	-- TrackerPanel
	["Objective Tracker Kit"] = "Набор отслеживания задач", -- draft
	["The objective tracker dressed in the painted kit on the game's own layout."] = "Отслеживание задач в рисованном наборе в раскладке игры.", -- draft
	-- SocialPanel
	["Social Panel Kit"] = "Набор окна общения", -- draft
	["The social window (contacts, raid, quick join) dressed in the painted kit on the game's own layout."] = "Окно общения (контакты, рейд, быстрое присоединение) в рисованном наборе в раскладке игры.", -- draft
	-- ChatPanel
	["Chat Panel Kit"] = "Набор панели чата", -- draft
	["The chat windows (frame, tabs, edit box, buttons) dressed in the painted kit on the game's own layout."] = "Окна чата (рамка, вкладки, поле ввода, кнопки) в рисованном наборе в раскладке игры.", -- draft
	-- DamageMeterPanel
	["Damage Meter Kit"] = "Набор счетчика урона", -- draft
	["The game's damage meter (window, header, entry bars, breakdown windows) dressed in the painted kit on its own layout."] = "Счетчик урона игры (окно, шапка, полосы записей, окна подробностей) в рисованном наборе в его собственной раскладке.", -- draft
	-- TooltipPanel
	["Tooltip Kit"] = "Набор подсказок", -- draft
	["Tooltips dressed in the painted kit: the stone box with the single rail, the unit health bar in the bracket."] = "Подсказки в рисованном наборе: каменное поле с одинарной планкой, полоса здоровья юнита в скобе.", -- draft
	-- NameplatePanel
	["Nameplate Kit"] = "Набор индикаторов здоровья", -- draft
	["Nameplates dressed in the painted kit: the health bar in the bracket, the cast bar on the single rail, the level circle on the orb."] = "Индикаторы здоровья в рисованном наборе: полоса здоровья в скобе, полоса заклинания на одинарной планке, круг уровня на сфере.", -- draft
	["Whole Plate Shade"] = "Тень всей таблички", -- draft
	["The UI Shade also follows the painted plate's own shape: round the level circle, round each end gem and along the bar, in every Nameplate Border look. It needs the UI Shade on (Look); its Shade Strength sets how dark it is. The name's own band is Nameplates' Name Shade."] = "Тень интерфейса также следует собственной форме рисованной таблички: вокруг круга уровня, вокруг каждого концевого самоцвета и вдоль полосы, в каждом облике «Рамки индикаторов здоровья». Нужна включённая «Тень интерфейса» (Облик); её «Сила тени» задаёт, насколько она темна. Собственная полоса имени — «Тень имени» в «Индикаторах здоровья».", -- draft
	["Elites, rares, rare elites and bosses stand out: a metal line over the name with a crest on it. Gold with a crown and wings for an elite, silver with a star for a rare, silver with a gold star and wings for a rare elite, and red-bronze scrollwork with a skull, winged at both ends, for a boss. The plate itself keeps its look."] = "Элита, редкие, редкие элитные и боссы выделяются: металлическая линия над именем с гербом. Золото с короной и крыльями для элиты, серебро со звездой для редкого, серебро с золотой звездой и крыльями для редкого элитного и красно-бронзовые завитки с черепом, крылатые с обоих концов, для босса. Сама табличка сохраняет свой облик.", -- draft
	-- Chat
	["Clean chat: hidden background and input art, short coloured channel tags, class coloured names."] = "Чистый чат: скрытые фон и оформление поля ввода, короткие цветные метки каналов, имена в цвете класса.", -- draft
	["Less frame, more talk. Short channel tags and class colours keep the log readable."] = "Меньше рамки, больше разговора. Короткие метки каналов и цвета классов держат журнал читаемым.", -- draft
	["Chat View"] = "Вид чата", -- draft
	["How the chat is shown. Game Windows: the game's chat windows and tabs. Minimal: one panel with a rail of round tabs on its left (one per chat window, a count of the lines you have not seen; Whispers last), each line under its sender's name, channel and time, and a row of round buttons under the lines: Say, Party, Raid, Instance, Guild, Yell, Whisper and Emote open the line you type in on that chat, then Channels, Friends, the fight history and these settings. A whisper puts a count on the Whispers tab and shows the Whispers widget; either opens one whisper window above the chat with every conversation in it, theirs left and yours right. Parchment (its own switch) puts both on the parchment sheet."] = "Как показывается чат. «Окна игры»: окна и вкладки чата игры. «Минимальный»: одна панель с полосой круглых вкладок слева (по одной на окно чата, со счётчиком непросмотренных строк; «Шёпот» последней), каждая строка под именем отправителя, каналом и временем, и ряд круглых кнопок под строками: «Сказать», «Группа», «Рейд», «Подземелье», «Гильдия», «Крикнуть», «Шепнуть» и «Эмоция» открывают строку ввода в этом чате, затем «Каналы», «Друзья», история боёв и эти настройки. Шёпот ставит счётчик на вкладку «Шёпот» и показывает виджет шёпота; любой из них открывает одно окно шёпота над чатом со всеми разговорами, их реплики слева, ваши справа. «Пергамент» (свой переключатель) кладёт оба на лист пергамента.", -- draft
	["Game Windows"] = "Окна игры", -- draft
	["Minimal"] = "Минимальный", -- draft
	["The chat windows' background: a dark panel of the palette behind the window, its tabs and its input box (Dark), the game's own (Game), or none at all (None). Under the painted chat (its Painted Skin, the reskin on) its stone instead. With the Minimal Chat View: None leaves its panel clear, Dark and Game keep its dark panel; Parchment lays the parchment sheet over it."] = "Фон окон чата: тёмная панель палитры за окном, его вкладками и полем ввода («Тёмный»), фон игры («Игра») или никакого («Нет»). Под рисованным чатом (его рисованный облик, облик включён) — вместо этого его камень. С «Минимальным» видом чата: «Нет» оставляет его панель чистой, «Тёмный» и «Игра» сохраняют тёмную панель; «Пергамент» кладёт поверх лист пергамента.", -- draft
	["Set The Background Opacity"] = "Задать непрозрачность фона", -- draft
	["Give every chat window the same background opacity, kept in your profile. Off, each window keeps the opacity set in its tab's menu."] = "Даёт каждому окну чата одинаковую непрозрачность фона, хранимую в вашем профиле. Выкл.: каждое окно сохраняет непрозрачность, заданную в меню его вкладки.", -- draft
	["Background Opacity"] = "Непрозрачность фона", -- draft
	["How solid the chat windows' background is. Moving the Background slider in a chat tab's menu changes this too."] = "Насколько плотен фон окон чата. Ползунок «Фон» в меню вкладки чата тоже меняет это.", -- draft
	["Border Opacity"] = "Непрозрачность рамки", -- draft
	["How solid the painted border round the chat windows and their button column is, and its shade (the painted chat: its Painted Skin, the reskin on)."] = "Насколько плотна рисованная рамка вокруг окон чата и их колонки кнопок, и её тень (рисованный чат: его рисованный облик, облик включён).", -- draft
	["Hide Input Box Art"] = "Скрыть оформление поля ввода", -- draft
	["Hide the border and background art of the chat input box."] = "Скрывает оформление рамки и фона поля ввода чата.", -- draft
	["Hide Tab Background"] = "Скрыть фон вкладок", -- draft
	["Hide the background art behind the chat tabs. The tab text stays."] = "Скрывает оформление за вкладками чата. Текст вкладок остаётся.", -- draft
	["Tabs Only On Mouseover"] = "Вкладки только при наведении", -- draft
	["Chat tab names are invisible until the mouse is over the chat. Tabs flashing with new whispers stay visible. It adds to the Fader's Chat fade: both fade the tabs, so with both on the two fades multiply. Does nothing under the painted chat (its Painted Skin, the reskin on), which keeps its tabs shown."] = "Названия вкладок чата не видны, пока мышь не над чатом. Вкладки, мигающие от нового шёпота, остаются видимыми. Добавляется к угасанию чата в «Угасании»: оба гасят вкладки, так что при обоих включённых угасания перемножаются. Ничего не делает под рисованным чатом (его рисованный облик, облик включён), который держит вкладки видимыми.", -- draft
	["Input Box On Top"] = "Поле ввода сверху", -- draft
	["Move the chat input box above the chat window and its tabs instead of below it."] = "Ставит поле ввода чата над окном чата и его вкладками, а не под ними.", -- draft
	["Input Box Only While Typing"] = "Поле ввода только при наборе", -- draft
	["The chat input box shows only while you type: Enter (or /) brings it up, and it goes again once you send the line or press Escape. It sets the game's Chat Style to Classic while on, and gives your own back when off. The change shows from the next line you type."] = "Поле ввода чата видно только пока вы пишете: Enter (или /) вызывает его, и оно исчезает после отправки строки или нажатия Esc. Пока включено, ставит «Стиль чата» игры на «Классический» и возвращает ваш при выключении. Изменение видно со следующей строки.", -- draft
	["Chat Buttons"] = "Кнопки чата", -- draft
	["The game's chat buttons in their column left of the chat: Friends at the top, Channels, the chat menu (Say, Party, Guild, Yell, whisper and reply, emotes, and the language you speak). While you speak more than one language, the one you speak shows at the right end of the line you type in. Off: the column is hidden."] = "Кнопки чата игры в колонке слева от чата: «Друзья» сверху, «Каналы», меню чата («Сказать», «Группа», «Гильдия», «Крикнуть», шёпот и ответ, эмоции и язык, на котором вы говорите). Если вы говорите на нескольких языках, текущий виден на правом конце строки ввода. Выкл.: колонка скрыта.", -- draft
	["Smooth Scrolling"] = "Плавная прокрутка", -- draft
	["The mouse wheel glides the chat text up and down instead of jumping a line at a time, in the chat windows and the whisper windows. Off, or with Reduce Motion on, it jumps as before."] = "Колёсико мыши плавно двигает текст чата вверх и вниз, а не прыгает по строке, в окнах чата и шёпота. Выкл. или при «Меньше движения» — прыгает, как раньше.", -- draft
	["Channels"] = "Каналы", -- draft
	["Short Channel Tags"] = "Короткие метки каналов", -- draft
	["Replace [Guild], [Party], [1. General] and so on with short, saturated coloured tags."] = "Заменяет [Гильдия], [Группа], [1. Общий] и т. п. короткими насыщенными цветными метками.", -- draft
	["Hide Brackets"] = "Скрыть скобки", -- draft
	["Also remove the square brackets around the short channel tags."] = "Убирает и квадратные скобки вокруг коротких меток каналов.", -- draft
	["Whisper Popup Window"] = "Всплывающее окно шёпота", -- draft
	["A whisper opens a small window of its own, one per person, with the conversation and a box to answer in, instead of a new chat tab. Whispers still show in the main chat. Switching it off puts the game's own whisper setting back."] = "Шёпот открывает маленькое собственное окно, по одному на человека, с разговором и полем для ответа, вместо новой вкладки чата. Шёпот по-прежнему виден в основном чате. Выключение возвращает собственный параметр шёпота игры.", -- draft
	-- CombatText
	["The text that floats over your character in a fight (damage taken, heals, Dodge and Parry, procs, resources gained) in MelloUI's look, in one of three styles, or the game's own."] = "Текст, всплывающий над вашим персонажем в бою (полученный урон, исцеление, уклонение и парирование, срабатывания, полученные ресурсы), в облике MelloUI в одном из трёх стилей, или текст игры.", -- draft
	["Your hits taken, heals and procs in MelloUI's soft look, or the game's own text."] = "Полученные удары, исцеление и срабатывания в мягком облике MelloUI или текст игры.", -- draft
	["Combat Text Style"] = "Стиль текста боя", -- draft
	["Who draws the text over your character. Game: the game's own, as it always was. Lanes: damage taken falls on your left, healing rises on your right, procs and Dodge / Parry above your head, resources under your feet. Feed: one column over your portrait, the newest on top. Classic: one stream over your head, like the game's, in MelloUI's font and soft shade."] = "Кто рисует текст над вашим персонажем. «Игра»: текст игры, как всегда. «Дорожки»: полученный урон падает слева, исцеление поднимается справа, срабатывания и уклонение / парирование над головой, ресурсы у ног. «Лента»: одна колонка над портретом, новое сверху. «Классика»: один поток над головой, как у игры, шрифтом и мягкой тенью MelloUI.", -- draft
	["Game (Blizzard)"] = "Игра (Blizzard)", -- draft
	["Lanes: round your character"] = "Дорожки: вокруг персонажа", -- draft
	["Feed: over your portrait"] = "Лента: над портретом", -- draft
	["Classic: one stream, restyled"] = "Классика: один поток, по-новому", -- draft
	["Your Damage"] = "Ваш урон", -- draft
	["The numbers of the damage you deal, over the enemies. Game: the game's own numbers, as always. Rise, Beside, Fan or Stack: drawn by MelloUI at each enemy's nameplate in its soft look, the game's numbers switched off meanwhile: crits gold and bigger, spells violet, a dodge or parry as a word, about a second and a half each, only on enemies you or your pet are fighting. Beside starts them at the plate's right end, so the name stays readable. Rise, Beside, Fan and Stack draw your hits while you play solo. In a group, or where the game keeps threat hidden, the game's own numbers show, because only they know whose hit it is. With enemy nameplates off, the game's own numbers show too (the plates are where MelloUI draws)."] = "Числа наносимого вами урона над врагами. «Игра»: числа игры, как всегда. «Подъём», «Сбоку», «Веер» или «Стопка»: рисуются MelloUI у индикатора здоровья каждого врага в мягком облике, а числа игры тем временем выключены: криты золотые и крупнее, заклинания фиолетовые, уклонение или парирование словом, около полутора секунд каждое, только на врагах, с которыми сражаетесь вы или питомец. «Сбоку» начинает их у правого края индикатора, чтобы имя читалось. «Подъём», «Сбоку», «Веер» и «Стопка» рисуют ваши удары, пока вы играете в одиночку. В группе или там, где игра скрывает угрозу, видны числа игры: только они знают, чей это удар. При выключенных индикаторах здоровья врагов тоже видны числа игры (MelloUI рисует на индикаторах).", -- draft
	["Rise: up from the enemy"] = "Подъём: вверх от врага", -- draft
	["Beside: up from the plate's side"] = "Сбоку: вверх от края индикатора", -- draft
	["Fan: up, left and right"] = "Веер: вверх, влево и вправо", -- draft
	["Stack: a column beside the enemy"] = "Стопка: колонка рядом с врагом", -- draft
	["Your Damage Size"] = "Размер «Вашего урона»", -- draft
	["The size of Your Damage's numbers over the enemies (Rise, Beside, Fan and Stack), whatever the text around you. 70% by default."] = "Размер чисел «Вашего урона» над врагами («Подъём», «Сбоку», «Веер» и «Стопка»), каким бы ни был текст вокруг вас. По умолчанию 70%.", -- draft
	["Plays a few made-up lines (hits, a crit, heals, a Dodge, a proc) in the chosen style, so you can compare them without a fight. Also /mello combattext test."] = "Проигрывает несколько выдуманных строк (удары, крит, исцеление, уклонение, срабатывание) в выбранном стиле, чтобы сравнить их без боя. Также /mello combattext test.", -- draft
	["a short burst in the chosen style"] = "короткая серия в выбранном стиле", -- draft
	["Text Around You"] = "Текст вокруг вас", -- draft
	["The size of the text around your character in the Lanes, Feed and Classic styles. Crits are a third bigger. The Fonts' Interface text and Titles & headers sizes do not change it (only their faces). The numbers over the enemies have their own size: Numbers Over Enemies."] = "Размер текста вокруг персонажа в стилях «Дорожки», «Лента» и «Классика». Криты на треть крупнее. Размеры «Текста интерфейса» и «Заголовков» в «Шрифтах» его не меняют (только их начертания). У чисел над врагами свой размер: «Числа над врагами».", -- draft
	["Notices In Title Font"] = "Оповещения шрифтом заголовков", -- draft
	["Procs and auras in the title font, as the window titles. Off: in the text font, as the numbers."] = "Срабатывания и эффекты шрифтом заголовков, как заголовки окон. Выкл.: шрифтом текста, как числа.", -- draft
	["Shade Size"] = "Размер тени", -- draft
	["The size of the soft shade behind the combat text, the text over you and Your Damage alike. 100% is the notices' shade; less hugs the numbers closer; 0% shows none."] = "Размер мягкой тени за текстом боя — и над вами, и у «Вашего урона». 100% — тень оповещений; меньше — плотнее к числам; 0% — без тени.", -- draft
	["Lane Spread"] = "Разброс дорожек", -- draft
	["How far from your character the damage and healing lanes run, left and right. Move the whole text in Edit Layout."] = "Насколько далеко от персонажа идут дорожки урона и исцеления, влево и вправо. Весь текст двигается в «Изменить раскладку».", -- draft
	["Most Lines"] = "Наибольшее число строк", -- draft
	["The most lines around your character at once: per lane for Lanes, in the stream for Classic, in the column for Feed. The oldest goes first. Your Damage keeps its own count per enemy."] = "Наибольшее число строк вокруг персонажа одновременно: на дорожку для «Дорожек», в потоке для «Классики», в колонке для «Ленты». Самая старая уходит первой. «Ваш урон» ведёт свой счёт на каждого врага.", -- draft
	["Damage Taken"] = "Полученный урон", -- draft
	["The damage you take, crits bigger."] = "Урон, который вы получаете, криты крупнее.", -- draft
	["The healing you get, and shields put on you."] = "Исцеление, которое вы получаете, и щиты на вас.", -- draft
	["Procs & Auras"] = "Срабатывания и эффекты", -- draft
	["Abilities that light up (Overpower!), auras you gain or lose, interrupts and dispels."] = "Загорающиеся способности («Превосходство!»), получаемые и теряемые эффекты, прерывания и рассеивания.", -- draft
	["Dodge, Parry & Block"] = "Уклонение, парирование и блок", -- draft
	["Attacks that miss you: misses, dodges, parries, blocks, absorbs, resists and immunes."] = "Атаки мимо вас: промахи, уклонения, парирования, блоки, поглощения, сопротивления и невосприимчивость.", -- draft
	["Resources Gained"] = "Полученные ресурсы", -- draft
	["Mana, rage, energy and focus you gain (+12 Rage)."] = "Мана, ярость, энергия и концентрация, которые вы получаете (+12 ярости).", -- draft
	["Entering & Leaving Combat"] = "Вход в бой и выход", -- draft
	["A short line when a fight starts and when it ends."] = "Короткая строка, когда бой начинается и когда заканчивается.", -- draft
	["Reputation & Honor"] = "Репутация и честь", -- draft
	["Reputation and honor you gain."] = "Получаемые репутация и честь.", -- draft
	["Damage Over Enemies"] = "Урон над врагами", -- draft
	["The numbers of your damage over the enemies (the game's own setting: drawn by the game in the Game Numbers Font, at Numbers Over Enemies' size)."] = "Числа вашего урона над врагами (собственный параметр игры: рисуются игрой «Шрифтом чисел игры» в размере «Чисел над врагами»).", -- draft
	["DoT Ticks Over Enemies"] = "Тики DoT над врагами", -- draft
	["Your damage over time ticks over the enemies (the game's own setting)."] = "Тики вашего периодического урона над врагами (собственный параметр игры).", -- draft
	["Pet Damage Over Enemies"] = "Урон питомца над врагами", -- draft
	["Your pet's damage over the enemies (the game's own setting)."] = "Урон вашего питомца над врагами (собственный параметр игры).", -- draft
	["Healing Over Friends"] = "Исцеление над союзниками", -- draft
	["The numbers of your healing over the ones you heal (the game's own setting)."] = "Числа вашего исцеления над теми, кого вы лечите (собственный параметр игры).", -- draft
	-- HealFlight
	["Heal Effects"] = "Эффекты исцеления", -- draft
	["Your heals on your group as light: a cast heal gathers on your cast bar and flies to the frame of the one you heal; an instant one lands on their frame at once. Each kind lands its own way: heals over time, shields, protection, a heal to full, a resurrection."] = "Ваше исцеление группы светом: заклинание исцеления собирается на вашем индикаторе заклинаний и летит к рамке того, кого вы лечите; мгновенное сразу ложится на рамку. Каждый вид приземляется по-своему: периодическое исцеление, щиты, защита, полное исцеление, воскрешение.", -- draft
	["Your heals fly from your cast bar to the frame of the one you heal."] = "Ваше исцеление летит с индикатора заклинаний к рамке того, кого вы лечите.", -- draft
	["How your heals look. By Class: Holy for priests and paladins, Nature for druids, Water for shamans (Holy for anyone else). Water: water circles your cast bar, a winding stream throws off droplets, a splash lands; a shield is a water bubble, a heal to full a geyser. Holy: gold sparks spiral into your spell's icon, a gold comet flies, a white flash and a burst of rays land, rune marks linger round the frame. Nature: green and gold ribbons circle your cast bar, ribbons fly shedding leaves, leaves burst and rise. Quiet: your cast bar's fill glows, a thin thread of light flies, the frame's border flares. Each kind lands its own way in each look: a heal over time sinks in, a shield wraps the frame in a barrier, protection puts a crest over it, a heal to full raises a column of light, a resurrection lights the fallen one's frame."] = "Как выглядит ваше исцеление. «По классу»: «Свет» для жрецов и паладинов, «Природа» для друидов, «Вода» для шаманов («Свет» для остальных). «Вода»: вода кружит у индикатора заклинаний, извилистый поток роняет капли, приземляется всплеск; щит — водяной пузырь, полное исцеление — гейзер. «Свет»: золотые искры спиралью уходят в значок заклинания, летит золотая комета, приземляются белая вспышка и всплеск лучей, руны задерживаются вокруг рамки. «Природа»: зелёные и золотые ленты кружат у индикатора заклинаний, ленты летят, роняя листья, листья взрываются и поднимаются. «Тихо»: заливка индикатора заклинаний светится, летит тонкая нить света, рамка вспыхивает. Каждый вид приземляется по-своему в каждом облике: периодическое исцеление впитывается, щит окутывает рамку барьером, защита ставит над ней герб, полное исцеление поднимает столб света, воскрешение озаряет рамку павшего.", -- draft
	["By Class: Holy, Nature or Water"] = "По классу: Свет, Природа или Вода", -- draft
	["Holy: a gold comet"] = "Свет: золотая комета", -- draft
	["Nature: ribbons and leaves"] = "Природа: ленты и листья", -- draft
	["Water: a stream and a splash"] = "Вода: поток и всплеск", -- draft
	["Quiet: a thread of light"] = "Тихо: нить света", -- draft
	["Flying Light"] = "Летящий свет", -- draft
	["The light that flies from your cast bar to the frame when a cast heal ends (Chain Heal's hops too). Off: the heal lands on the frame the moment the cast ends, as an instant one does; the glow on your cast bar while you cast and every effect on the frames stay."] = "Свет, который летит с индикатора заклинаний к рамке, когда заканчивается заклинание исцеления (и прыжки «Цепного исцеления»). Выкл.: исцеление ложится на рамку в момент окончания заклинания, как мгновенное; свечение индикатора заклинаний во время заклинания и все эффекты на рамках остаются.", -- draft
	["Heal Over Time Ticks"] = "Тики периодического исцеления", -- draft
	["While a heal over time of yours runs (Renew, Rejuvenation, Regrowth's), each of its ticks plays a small pulse on the frame: a ring and three motes (Holy), a leaf (Nature), a drop and a ripple (Water), the border's breath (Quiet, and in a raid). Timed from the game's spell data: Renew ticks five times in 15 seconds."] = "Пока действует ваше периодическое исцеление («Обновление», «Омоложение», у «Восстановления»), каждый тик играет на рамке маленький импульс: кольцо и три искры («Свет»), лист («Природа»), капля и рябь («Вода»), дыхание рамки («Тихо», и в рейде). Время по данным заклинаний игры: «Обновление» тикает пять раз за 15 секунд.", -- draft
	["Plays the chosen look once: the light gathers where your cast bar stands and flies to your own frame in your party or raid frames (or your player frame); with Flying Light off it lands there at once."] = "Проигрывает выбранный облик один раз: свет собирается там, где ваш индикатор заклинаний, и летит к вашей рамке в рамках группы или рейда (или к рамке игрока); при выключенном «Летящем свете» ложится туда сразу.", -- draft
	["a made-up heal on you"] = "выдуманное исцеление на вас", -- draft
	["Every Kind"] = "Все виды", -- draft
	["Plays each kind's landing on your own frame, one after another: a heal over time, a shield, protection, a heal to full, a resurrection."] = "Проигрывает приземление каждого вида на вашей рамке, один за другим: периодическое исцеление, щит, защита, полное исцеление, воскрешение.", -- draft
	["each kind's landing on your frame"] = "приземление каждого вида на вашей рамке", -- draft
	-- FrameEffects
	["Cooldown Effects"] = "Эффекты способностей", -- draft
	["Your group's frames show their big moments: a roar's square ripples, a taunt, Shield Wall's steel, Last Stand's heartbeat, an immunity's barrier, an evasion's afterimages -- on your own frame when you use one, on a group mate's when they do."] = "Рамки вашей группы показывают их громкие моменты: квадратные волны крика, провокацию, сталь «Глухой обороны», сердцебиение «Ни шагу назад», барьер неуязвимости, остаточные образы ускользания — на вашей рамке, когда используете вы, на рамке товарища, когда он.", -- draft
	["Shield Wall, Last Stand, a roar: your group's frames show their big moments."] = "«Глухая оборона», «Ни шагу назад», крик: рамки вашей группы показывают громкие моменты.", -- draft
	["Every Effect"] = "Все эффекты", -- draft
	["Plays each kind on your own frame, one after another, its name and an example on the screen: a roar (Challenging Shout), a taunt, damage taken down (Shield Wall), more health (Last Stand), an immunity, a dodge or parry (Evasion)."] = "Проигрывает каждый вид на вашей рамке, один за другим, с названием и примером на экране: крик («Вызывающий крик»), провокация, снижение получаемого урона («Глухая оборона»), больше здоровья («Ни шагу назад»), неуязвимость, уклонение или парирование («Ускользание»).", -- draft
	["each kind on your own frame"] = "каждый вид на вашей рамке", -- draft
	["Whose"] = "Чьи", -- draft
	["Whose big moments play on the frames. Yours: when you use one (Challenging Shout, Shield Wall, Last Stand, Divine Shield, Evasion ...), your own frame in your party or raid frames plays its effect for as long as it lasts (a roar: 2 seconds). Your group's: when someone of your party or raid uses one, their frame plays it -- you see at a glance who just used Shield Wall or Divine Shield, and whose roar just pulled."] = "Чьи громкие моменты играют на рамках. «Ваши»: когда вы используете способность («Вызывающий крик», «Глухая оборона», «Ни шагу назад», «Божественный щит», «Ускользание» ...), ваша рамка в рамках группы или рейда играет её эффект, пока она длится (крик — 2 секунды). «Группы»: когда кто-то из вашей группы или рейда использует такую способность, его рамка играет её — с одного взгляда видно, кто только что применил «Глухую оборону» или «Божественный щит» и чей крик только что притянул врагов.", -- draft
	["Yours And Your Group's"] = "Ваши и группы", -- draft
	["Yours"] = "Ваши", -- draft
	["Your Group's"] = "Группы", -- draft
	-- GroupFrames
	["Group Frames"] = "Рамки группы", -- draft
	["MelloUI's own party and raid frames in place of the game's: their size, layout and sorting, every bar's colour (class, your own, by health), the power bar, the texts, and your own aura indicators on them."] = "Собственные рамки группы и рейда MelloUI вместо игровых: их размер, раскладка и сортировка, цвет каждой полосы (класс, ваш, по здоровью), полоса ресурса, тексты и ваши собственные индикаторы эффектов на них.", -- draft
	["Your party and raid as you want them: colours, bars, texts, and your HoTs and shields at a glance."] = "Ваша группа и рейд такими, как вы хотите: цвета, полосы, тексты и ваши HoT и щиты с одного взгляда.", -- draft
	["In A Party"] = "В группе", -- draft
	["In a party: these frames, or MelloUI's normal party frames (the game's party frames with their portraits, in the painted look). With the normal ones, you show as one of them while solo too (Show Yourself While Solo), so you can see your heals and indicators on it. In a raid these frames show. The normal party frames show as the game's Edit Mode sets them: with Raid-Style Party Frames on there, the game shows none of its normal ones."] = "В группе: эти рамки или обычные рамки группы MelloUI (рамки группы игры с портретами в рисованном облике). С обычными вы и в одиночку показываетесь как одна из них («Показывать себя в одиночку»), чтобы видеть на ней своё исцеление и индикаторы. В рейде видны эти рамки. Обычные рамки группы видны так, как их задаёт режим редактирования игры: с включёнными там «Рамками группы в стиле рейда» игра не показывает ни одной обычной.", -- draft
	["Party Frames (Portraits)"] = "Рамки группы (портреты)", -- draft
	["Show Yourself In Your Party"] = "Показывать себя в группе", -- draft
	["Your own frame among your party's."] = "Ваша собственная рамка среди рамок группы.", -- draft
	["Show Yourself While Solo"] = "Показывать себя в одиночку", -- draft
	["While you are not in a group, your own frame stands where your party's will, with your indicators on it. Move it in Edit Layout. With In A Party set to Party Frames, it is a normal party frame where the game's party frames stand (move those in Edit Mode)."] = "Пока вы не в группе, ваша рамка стоит там, где будут рамки группы, с вашими индикаторами. Переместите её в «Изменить раскладку». Если «В группе» = «Рамки группы», это обычная рамка группы там, где стоят рамки группы игры (их двигают в режиме редактирования).", -- draft
	["Frame Width"] = "Ширина рамки", -- draft
	["Each frame's width (the game's raid frame: 72)."] = "Ширина каждой рамки (рамка рейда игры: 72).", -- draft
	["Frame Height"] = "Высота рамки", -- draft
	["Each frame's height (the game's raid frame: 36)."] = "Высота каждой рамки (рамка рейда игры: 36).", -- draft
	["Party Spacing"] = "Отступ группы", -- draft
	["The room between two of the party's frames. Also on the party's plate in Edit Layout (right-click it)."] = "Расстояние между двумя рамками группы. Также на табличке группы в «Изменить раскладку» (правый щелчок).", -- draft
	["Party Grows"] = "Рост группы", -- draft
	["Which way the party's frames line up from where you placed them."] = "В какую сторону выстраиваются рамки группы от места, где вы их поставили.", -- draft
	["Party Order"] = "Порядок группы", -- draft
	["The order of the party's frames: tanks, then healers, then damage; the game's group order; or by name."] = "Порядок рамок группы: танки, затем лекари, затем урон; порядок группы игры; или по имени.", -- draft
	["By Role (Tanks, Healers, Damage)"] = "По роли (танки, лекари, урон)", -- draft
	["Group Order"] = "Порядок группы", -- draft
	["By Name"] = "По имени", -- draft
	["Raid Grouping"] = "Группировка рейда", -- draft
	["How the raid's frames are grouped: by raid group (1 to 8), by role, by class, or one list."] = "Как группируются рамки рейда: по группе рейда (1–8), по роли, по классу или одним списком.", -- draft
	["By Group"] = "По группе", -- draft
	["By Role"] = "По роли", -- draft
	["By Class"] = "По классу", -- draft
	["One List"] = "Одним списком", -- draft
	["Raid Fills"] = "Заполнение рейда", -- draft
	["Down a column then the next column across, or across a row then the next row down."] = "Вниз по столбцу, затем следующий столбец, или вдоль ряда, затем следующий ряд вниз.", -- draft
	["Down, Then Across"] = "Вниз, затем вбок", -- draft
	["Across, Then Down"] = "Вбок, затем вниз", -- draft
	["Frames Per Column / Row"] = "Рамок в столбце / ряду", -- draft
	["How many frames in a column (or a row) before the next one starts. 5 lines the raid up by its groups."] = "Сколько рамок в столбце (или ряду), прежде чем начнётся следующий. 5 выстраивает рейд по группам.", -- draft
	["Raid Spacing"] = "Отступ рейда", -- draft
	["The room between two of the raid's frames in a column (or a row). Also on the raid's plate in Edit Layout (right-click it)."] = "Расстояние между двумя рамками рейда в столбце (или ряду). Также на табличке рейда в «Изменить раскладку» (правый щелчок).", -- draft
	["Gap Between Columns / Rows"] = "Промежуток между столбцами / рядами", -- draft
	["The room between two columns (or rows) of the raid."] = "Расстояние между двумя столбцами (или рядами) рейда.", -- draft
	["Out Of Range Opacity"] = "Непрозрачность вне досягаемости", -- draft
	["How far a member too far away for your heals fades. 100%: no fade."] = "Насколько гаснет участник, слишком далёкий для вашего исцеления. 100%: не гаснет.", -- draft
	["Health Bar Opacity"] = "Непрозрачность полосы здоровья", -- draft
