	["The bars glide to a new value instead of jumping."] = "Полосы плавно переходят к новому значению, а не прыгают.", -- draft
	["What lies behind the health bar: a flat colour (Background Colour), one of MelloUI's backgrounds (stone, concrete, parchment, the dark gradients...), or none."] = "Что лежит за полосой здоровья: сплошной цвет («Цвет фона»), один из фонов MelloUI (камень, бетон, пергамент, тёмные градиенты...) или ничего.", -- draft
	["Flat colour"] = "Сплошной цвет", -- draft
	["Background Colour"] = "Цвет фона", -- draft
	["The colour behind the health bar: one of yours, or the member's class colour."] = "Цвет за полосой здоровья: один из ваших или цвет класса участника.", -- draft
	["Class Colour"] = "Цвет класса", -- draft
	["My Background Colour"] = "Мой цвет фона", -- draft
