	["How solid the background is."] = "Насколько плотен фон.", -- draft
	["Missing Health"] = "Недостающее здоровье", -- draft
	["The part of the bar a member has lost, in a colour of its own: yours, their class colour, or by health."] = "Часть полосы, которую участник потерял, своим цветом: вашим, цветом его класса или по здоровью.", -- draft
	["By Health"] = "По здоровью", -- draft
	["My Missing Health Colour"] = "Мой цвет недостающего здоровья", -- draft
