	["Power Bar"] = "Полоса ресурса", -- draft
	["Who shows a power bar (mana, rage, energy) under their health."] = "Кто показывает полосу ресурса (мана, ярость, энергия) под здоровьем.", -- draft
	["Healers"] = "Лекари", -- draft
