	["Your Power Bar While Solo"] = "Ваша полоса ресурса в одиночку", -- draft
	["Your own power bar while you play solo, whatever your role."] = "Ваша полоса ресурса, пока вы играете в одиночку, какой бы ни была ваша роль.", -- draft
	["Power Bar Height"] = "Высота полосы ресурса", -- draft
	["How tall the power bar is."] = "Насколько высока полоса ресурса.", -- draft
	["Power Colour"] = "Цвет ресурса", -- draft
	["The power bar's colour: the power's own (blue mana, red rage, yellow energy), the member's class colour, or one of yours."] = "Цвет полосы ресурса: цвет самого ресурса (синяя мана, красная ярость, жёлтая энергия), цвет класса участника или один из ваших.", -- draft
	["Power Type"] = "Тип ресурса", -- draft
